\section{Introduction}

\subsection{Motivation}
The Collatz map, $n\mapsto n/2$ for even $n$ and $n\mapsto 3n+1$ for odd $n$, is the standard
example of an arithmetic dynamical system whose global behaviour lies far beyond current
techniques.  A recurring hope for such problems is that harmonic analysis will supply the
missing pseudorandomness: encode the step data in an exponential sum, prove substantial
cancellation, and deduce equidistribution and, with luck, statements about hitting times or
the absence of divergent orbits.

This paper carries out that programme precisely for the simplest available statistic, the
\emph{one-step phase transform}, and determines its exact content.  The outcome is a complete
answer with a strongly negative dynamical component: the sum converges after normalization to
an explicit two-term trigonometric amplitude; the modulus of that amplitude is a single cosine;
its zero set is an arithmetic progression determined by the multiplier; and the statistic is
provably insensitive to any modification of the map on a density-zero set of inputs.  We regard
these negative results as the substance of the paper: drawing an exact boundary around the reach
of a method is more useful than an unquantified failure, and the boundary here is sharp enough to
indicate exactly which refinements can still carry information.

\subsection{Conventions}
Throughout, $a\ge1$ is an integer multiplier (classically $a=3,5,7$), $\omega\in\mathbb{R}$ is a
frequency, and $N\ge1$ an integer cutoff.  We write $e(x)=\exp(2\pi ix)$ and use freely
$e(x+y)=e(x)e(y)$, $|e(x)|=1$, $e(0)=1$.

\begin{lemma}[Chord identities]\label{lem:chord}
For all real $t$ and $x$,
\[
|1+e(t)|=2\,|\cos(\pi t)|,\qquad |e(x)-1|=2\,|\sin(\pi x)|.
\]
\end{lemma}

\begin{proof}[Proof sketch]
Factor out the half-angle: $1+e(t)=e(t/2)\bigl(e(-t/2)+e(t/2)\bigr)$ and
$e(-u)+e(u)=2\cos(2\pi u)$ with $u=t/2$; use $|e(t/2)|=1$.  Similarly
$e(x)-1=e(x/2)\bigl(e(x/2)-e(-x/2)\bigr)$ and $e(u)-e(-u)=2i\sin(2\pi u)$.
\end{proof}

An immediate consequence, used for the quantitative bound, is the Lipschitz estimate
\begin{equation}\label{eq:lip}
|e(x)-1|\le 2\pi|x|\qquad(x\in\mathbb{R}),
\end{equation}
which follows from $|\sin y|\le|y|$.

\section{The maps, the phase ratio, and the transform}

\begin{definition}[Accelerated map]
For integers $a\ge1$ and $n\ge1$,
\[
T_a(n)=\begin{cases} n/2, & n\equiv 0 \pmod 2,\\ an+1, & n\equiv 1 \pmod 2.\end{cases}
\]
\end{definition}

\begin{definition}[Phase ratio]
The phase ratio of the map at $n\ge1$ is $r_a(n)=T_a(n)/n$.
\end{definition}

The phase ratio, rather than $T_a(n)$ itself, is the correct object to place inside a character:
it is scale invariant, it is the multiplicative increment governing whether an orbit drifts up or
down, and it is bounded.

\begin{definition}[Cutoff transform]
For $a\ge1$, $\omega\in\mathbb{R}$, $N\ge0$,
\[
F_a(\omega,N)=\sum_{n=1}^{N}e\bigl(\omega\,r_a(n)\bigr).
\]
\end{definition}

Trivially $|F_a(\omega,N)|\le N$.  The classical hope is that $F_a(\omega,N)=o(N)$ for irrational
$\omega$; Section~\ref{sec:amp} shows this fails except on an explicit countable set.

\begin{proposition}[Branch splitting]\label{prop:branch}
For $n\ge1$: if $n$ is even then $r_a(n)=\tfrac12$ exactly, independently of $a$; if $n$ is odd then
$r_a(n)=a+\tfrac1n$.
\end{proposition}

\begin{proof}
For even $n$, $T_a(n)=n/2$, so the ratio is $1/2$.  For odd $n$, $T_a(n)=an+1$, so
$T_a(n)/n=a+1/n$.
\end{proof}

Thus $\{r_a(n)\}_{n\ge1}$ has exactly two accumulation points, $1/2$ and $a$, visited in strict
alternation, with a perturbation $1/n$ on the odd branch that is negligible after averaging.
Everything below is a consequence of Proposition~\ref{prop:branch}.

\begin{definition}[Limiting amplitude and branch gap]
\[
A_a(\omega)=\frac{e(\omega/2)+e(a\omega)}{2},\qquad
G_a(\omega)=\frac{e(a\omega)-e(\omega/2)}{2}.
\]
\end{definition}
Note $|G_a(\omega)|\le1$.

\section{The exact decomposition and the limit law}

\subsection{A finite even/odd decomposition}
Reindexing by $k=n-1\in\{0,\dots,N-1\}$, so that $k$ even corresponds to $n$ odd,
Proposition~\ref{prop:branch} gives the exact term identity
\begin{equation}\label{eq:term}
e\bigl(\omega r_a(k+1)\bigr)=
\begin{cases}
e(a\omega)\,e\!\left(\dfrac{\omega}{k+1}\right), & k \text{ even},\\[2mm]
e(\omega/2), & k \text{ odd}.
\end{cases}
\end{equation}

\begin{theorem}[Exact even/odd split]\label{thm:split}
For all $a,\omega,N$,
\[
F_a(\omega,N)=\left\lfloor\frac{N}{2}\right\rfloor e(\omega/2)
\;+\;e(a\omega)\sum_{\substack{0\le k<N\\ k\ \mathrm{even}}}e\!\left(\frac{\omega}{k+1}\right).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition $\{0,\dots,N-1\}$ by the parity of $k$ and apply \eqref{eq:term} termwise.  On the odd-$k$
part every summand equals the constant $e(\omega/2)$, and the number of odd $k<N$ is $\lfloor N/2\rfloor$;
on the even-$k$ part factor out the constant $e(a\omega)$.
\end{proof}

\subsection{The deviation sequence}
Compare each summand with a two-periodic model:
\[
d_a(\omega,k)=e\bigl(\omega r_a(k+1)\bigr)-\Bigl(A_a(\omega)+(-1)^kG_a(\omega)\Bigr).
\]
The bracketed model term equals $e(a\omega)$ for $k$ even and $e(\omega/2)$ for $k$ odd.

\begin{lemma}[Deviation formula]\label{lem:dev}
\[
d_a(\omega,k)=
\begin{cases}
e(a\omega)\left(e\!\left(\dfrac{\omega}{k+1}\right)-1\right), & k \text{ even},\\[2mm]
0, & k \text{ odd},
\end{cases}
\]
and consequently, by $|e(a\omega)|=1$ and \eqref{eq:lip},
\begin{equation}\label{eq:devbound}
|d_a(\omega,k)|\le\left|e\!\left(\frac{\omega}{k+1}\right)-1\right|\le\frac{2\pi|\omega|}{k+1}.
\end{equation}
In particular $d_a(\omega,k)\to0$ as $k\to\infty$.
\end{lemma}

Summing the definition of $d_a$ over $k<N$ yields the master identity
\begin{equation}\label{eq:master}
F_a(\omega,N)=N\,A_a(\omega)+G_a(\omega)\sum_{k=0}^{N-1}(-1)^k+\sum_{k=0}^{N-1}d_a(\omega,k).
\end{equation}
The middle sum is $0$ or $1$ according to the parity of $N$.

\subsection{The limit law}

\begin{theorem}[Limit law]\label{thm:limit}
For every integer $a\ge1$ and every $\omega\in\mathbb{R}$,
\[
\lim_{N\to\infty}\frac{F_a(\omega,N)}{N}=A_a(\omega)=\frac{e(\omega/2)+e(a\omega)}{2}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Divide \eqref{eq:master} by $N$.  The alternating term is bounded by $|G_a(\omega)|/N\le1/N\to0$.
The deviation term is the Ces\`aro average of a null sequence by Lemma~\ref{lem:dev}, hence tends to $0$.
\end{proof}

\subsection{A quantitative, multiplier-uniform error bound}

\begin{theorem}[Explicit error bound]\label{thm:error}
For all $a\ge1$, all $\omega\in\mathbb{R}$ and all $N\ge1$,
\[
\left|\frac{F_a(\omega,N)}{N}-A_a(\omega)\right|\le\frac{1+2\pi|\omega|(1+\log N)}{N}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By \eqref{eq:master},
\[
\frac{F_a(\omega,N)}{N}-A_a(\omega)=\frac1N\left(G_a(\omega)\sum_{k<N}(-1)^k+\sum_{k<N}d_a(\omega,k)\right).
\]
The first term has modulus at most $1$ since $|G_a(\omega)|\le1$ and the alternating sum is $0$ or $1$.
The second has modulus at most $\sum_{k<N}2\pi|\omega|/(k+1)\le2\pi|\omega|(1+\log N)$.
\end{proof}

Every constant is absolute: the bound does not depend on $a$ and depends on $\omega$ only through $|\omega|$.

\begin{corollary}[Uniform convergence on compacts]\label{cor:unif}
For every $M>0$ and $\varepsilon>0$ there is $N_0=N_0(M,\varepsilon)\ge1$ such that for all $N\ge N_0$,
all multipliers $a\ge1$ and all $|\omega|\le M$,
$\bigl|F_a(\omega,N)/N-A_a(\omega)\bigr|\le\varepsilon$.
\end{corollary}

\begin{proof}[Proof sketch]
The bound of Theorem~\ref{thm:error} is at most $\bigl(1+2\pi M(1+\log N)\bigr)/N\to0$ since $\log N=o(N)$.
\end{proof}

Corollary~\ref{cor:unif} is the corrected replacement for the impossible pointwise statement over all
irrational frequencies: the correct uniformity is in the multiplier and over compact frequency ranges.

\section{The amplitude: modulus, resonances, and the failure of pointwise decay}\label{sec:amp}

\begin{theorem}[Modulus formula]\label{thm:mod}
For all $a\ge1$ and $\omega\in\mathbb{R}$,
\[
|A_a(\omega)|=\left|\cos\!\left(\pi\left(a-\tfrac12\right)\omega\right)\right|.
\]
\end{theorem}

\begin{proof}[Proof sketch]
With $t=(a-\tfrac12)\omega$ one has $\omega/2+t=a\omega$, so
$e(\omega/2)+e(a\omega)=e(\omega/2)\bigl(1+e(t)\bigr)$.  Since $|e(\omega/2)|=1$,
Lemma~\ref{lem:chord} gives $|A_a(\omega)|=\tfrac12\cdot2|\cos(\pi t)|$.
\end{proof}

The entire leading-order spectral content is thus a single cosine of frequency $a-\tfrac12$: the multiplier
enters only through the dilation factor $2a-1$.

\begin{definition}
The \emph{resonance set} of the multiplier $a$ is $R_a=\{\omega\in\mathbb{R}: A_a(\omega)=0\}$.
\end{definition}

\begin{theorem}[Resonance classification]\label{thm:res}
$A_a(\omega)=0$ if and only if $(2a-1)\omega$ is an odd integer; equivalently
\[
R_a=\left\{\frac{2m+1}{2a-1}\;:\;m\in\mathbb{Z}\right\}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:mod}, $A_a(\omega)=0$ iff $\cos(\pi(a-\tfrac12)\omega)=0$, i.e.\ iff
$(a-\tfrac12)\omega=m+\tfrac12$ for some $m\in\mathbb{Z}$; multiply by $2$.
\end{proof}

Geometrically, $R_a$ consists of the frequencies at which the two branch phases $e(\omega/2)$ and $e(a\omega)$
are exactly antipodal, so the even and odd contributions annihilate one another.

\begin{theorem}[Cancellation exactly at resonance]\label{thm:cancel}
\begin{enumerate}
\item If $(2a-1)\omega$ is an odd integer then $F_a(\omega,N)/N\to0$, i.e.\ $F_a(\omega,N)=o(N)$.
\item If $A_a(\omega)\ne0$ then for all sufficiently large $N$,
$|F_a(\omega,N)|\ge\tfrac12|A_a(\omega)|\,N$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) is Theorem~\ref{thm:limit} with Theorem~\ref{thm:res}.  For (2), $|F_a(\omega,N)/N|\to|A_a(\omega)|>|A_a(\omega)|/2$,
so the strict inequality holds eventually; multiply by $N$.
\end{proof}

At resonance the cancellation is strong: Theorem~\ref{thm:error} gives $F_a(\omega,N)=O(1+|\omega|\log N)$,
and numerically $|F_3(1/5,N)|<8$ for $N$ up to $10^5$.

\begin{theorem}[Peak near zero]\label{thm:peak}
If $|(2a-1)\omega|\le\tfrac23$, then $|F_a(\omega,N)|\ge N/4$ for all sufficiently large $N$.
\end{theorem}

\begin{proof}[Proof sketch]
Put $t=(a-\tfrac12)\omega$, so $|t|\le1/3$ and $|\pi t|\le\pi/3$.  Cosine is even and decreasing on $[0,\pi]$,
so $\cos(\pi t)\ge\cos(\pi/3)=1/2$ and hence $|A_a(\omega)|\ge1/2$ by Theorem~\ref{thm:mod}.  Apply
Theorem~\ref{thm:cancel}(2).
\end{proof}

\begin{corollary}[Refutation of global pointwise decay]
There is no statement of the form ``$F_a(\omega,N)=o(N)$ for every irrational $\omega$'': the interval
$\bigl(0,\tfrac{2}{3(2a-1)}\bigr]$ contains irrational $\omega$, and every such $\omega$ violates it.
\end{corollary}

The obstruction is structural: by Proposition~\ref{prop:branch} the phase ratio has only two limiting values,
so $\{\omega r_a(n)\}$ is nowhere near equidistributed mod $1$, and continuity of the amplitude at $\omega=0$
(where $A_a(0)=1$) pins the transform to the trivial bound on a whole neighbourhood.

\section{The arithmetic of resonance sets}

\begin{theorem}[Trivial resonances]\label{thm:trivial}
For every $a\ge1$ and $t\in\mathbb{Z}$:
\begin{enumerate}
\item $A_a(2t+1)=0$: every multiplier resonates at every odd integer frequency;
\item $|A_a(2t)|=1$: at every even integer frequency the amplitude is maximal;
\item consequently $|A_a(t)|=|A_b(t)|$ for all $a,b\ge1$ and all $t\in\mathbb{Z}$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) $(2a-1)(2t+1)=2\bigl((2a-1)t+a-1\bigr)+1$ is odd; apply Theorem~\ref{thm:res}.
(2) $\pi(a-\tfrac12)(2t)=\bigl((2a-1)t\bigr)\pi$ and $|\cos(k\pi)|=1$.
(3) split on the parity of $t$.
\end{proof}

So no spectral discriminator between multipliers can be read off at integer frequencies, and in particular
none near $\omega=0$, the regime where the transform is largest.

\begin{lemma}[Diophantine form]\label{lem:dioph}
If $(2a-1)\omega=2m+1$ and $(2b-1)\omega=2k+1$ with $m,k\in\mathbb{Z}$, then
$(2b-1)(2m+1)=(2a-1)(2k+1)$.
\end{lemma}

\begin{proof}
Both sides equal $(2a-1)(2b-1)\omega$.
\end{proof}

\begin{theorem}[Common resonances of the classical multipliers are trivial]\label{thm:common}
For each pair $(a,b)\in\{(3,5),(3,7),(5,7)\}$ and every $\omega\in\mathbb{R}$,
\[
A_a(\omega)=0\ \wedge\ A_b(\omega)=0\iff \omega\in2\mathbb{Z}+1.
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) is Theorem~\ref{thm:trivial}(1).  ($\Rightarrow$) for $(a,b)=(3,5)$: Lemma~\ref{lem:dioph}
gives $9(2m+1)=5(2k+1)$, so $5\mid 2m+1$ and $2m+1=5(2s+1)$ for an integer $s$.  Then $5\omega=2m+1=5(2s+1)$,
so $\omega=2s+1$.  The pairs $(3,7)$ (with $13(2m+1)=5(2k+1)$) and $(5,7)$ (with $13(2m+1)=9(2k+1)$) are
identical modulo divisibility bookkeeping.
\end{proof}

\begin{theorem}[Spectral separation of $3n+1$, $5n+1$, $7n+1$]\label{thm:disc}
\begin{enumerate}
\item At $\omega=1/5$: $A_3(1/5)=0$, while $A_5(1/5)\ne0$ and $A_7(1/5)\ne0$; explicitly
$|A_5(1/5)|=\cos(\pi/10)\approx0.9511$ and $|A_7(1/5)|=|\cos(3\pi/10)|\approx0.5878$.  Hence
$F_3(1/5,N)=o(N)$ while $|F_5(1/5,N)|\ge0.475\,N$ and $|F_7(1/5,N)|\ge0.293\,N$ for large $N$.
\item At $\omega=1/9$: $A_5(1/9)=0$ while $A_3(1/9)\ne0\ne A_7(1/9)$.
\item At $\omega=1/13$: $A_7(1/13)=0$ while $A_3(1/13)\ne0\ne A_5(1/13)$.
\end{enumerate}
In particular $R_3$, $R_5$, $R_7$ are pairwise distinct.
\end{theorem}

\begin{proof}[Proof sketch]
For (1): $(2\cdot3-1)/5=1$ is odd, so $A_3(1/5)=0$.  For $a=5$, $A_5(1/5)=0$ would force $9/5=2m+1$,
i.e.\ $9=10m+5$, impossible over $\mathbb{Z}$; for $a=7$, $13=10m+5$ is likewise impossible.  Moduli follow from
Theorem~\ref{thm:mod} and the linear lower bounds from Theorem~\ref{thm:cancel}(2).  Items (2) and (3) are the
analogous computations with $5=18m+9$, $13=18m+9$ and $5=26m+13$, $9=26m+13$.
\end{proof}

\begin{theorem}[Mean square of the amplitude]\label{thm:meansq}
For every integer $a\ge1$,
\[
\int_0^2\bigl|A_a(\omega)\bigr|^2\,d\omega=1,
\]
i.e.\ the mean of $|A_a|^2$ over a full period equals $\tfrac12$, independently of $a$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:mod} and the double-angle formula,
$|A_a(\omega)|^2=\tfrac12+\tfrac12\cos\bigl(\pi(2a-1)\omega\bigr)$.  The constant contributes $1$ over $[0,2]$,
and
\[
\frac12\int_0^2\cos\bigl(\pi(2a-1)\omega\bigr)\,d\omega=\frac{\sin\bigl(2\pi(2a-1)\bigr)}{2\pi(2a-1)}=0,
\]
since $2(2a-1)$ is an even integer.
\end{proof}

Every $an+1$ map thus carries the same total spectral energy; only the positions of the zeros distinguish
multipliers, so any statistic integrating $|A_a|^2$ against a multiplier-independent weight over full periods
is blind.

\section{The no-go theorem: the one-step spectrum cannot see dynamics}

\begin{definition}[Generic transform]
For $r:\mathbb{Z}_{\ge1}\to\mathbb{R}$ put $F[r](\omega,N)=\sum_{n\le N}e(\omega r(n))$; thus
$F_a(\omega,N)=F[r_a](\omega,N)$.
\end{definition}

\begin{lemma}[Disagreement bound]\label{lem:disagree}
For all $r_1,r_2,\omega,N$,
\[
\bigl|F[r_1](\omega,N)-F[r_2](\omega,N)\bigr|\le 2\,\#\{1\le n\le N: r_1(n)\ne r_2(n)\}.
\]
\end{lemma}

\begin{proof}[Proof sketch]
Terms with $r_1(n)=r_2(n)$ cancel exactly; each remaining term is a difference of two unit vectors, of modulus
at most $2$.
\end{proof}

\begin{theorem}[Blindness to density-zero modification]\label{thm:blind}
Let $r_1,r_2:\mathbb{Z}_{\ge1}\to\mathbb{R}$ satisfy
$\#\{n\le N:r_1(n)\ne r_2(n)\}/N\to0$.  Then for every $\omega$,
\[
\frac{F[r_1](\omega,N)}{N}-\frac{F[r_2](\omega,N)}{N}\longrightarrow0 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Divide Lemma~\ref{lem:disagree} by $N$ and apply the density hypothesis.
\end{proof}

\begin{corollary}[Finite surgery is spectrally invisible]\label{cor:surgery}
Let $S$ be a finite set of positive integers and let $r$ agree with $r_a$ outside $S$.  Then
$F[r](\omega,N)/N\to A_a(\omega)$ for every $\omega$.
\end{corollary}

\begin{proof}[Proof sketch]
The disagreement count is at most $|S|$ for every $N$, hence of density zero; combine
Theorem~\ref{thm:blind} with Theorem~\ref{thm:limit}.
\end{proof}

\begin{remark}
Whether the $3n+1$ map possesses a nontrivial cycle, and what the stopping time of any particular integer is,
are assertions about finite sets of inputs --- precisely the data that Corollary~\ref{cor:surgery} shows the
normalized transform cannot detect.  Consequently no implication of the form ``cancellation in the one-step
cutoff sum $\Rightarrow$ an orbit hitting-time or cycle-exclusion statement'' can be valid, since the hypothesis
is invariant under modifications that change the conclusion.  Any spectral approach with dynamical content must
use a statistic that is \emph{not} invariant under density-zero surgery.
\end{remark}

\section{Algorithms and numerical verification}

\textbf{Algorithm A (direct evaluation).} Given $a,\omega,N$, accumulate $e(\omega r_a(n))$ for $n=1,\dots,N$:
$\Theta(N)$ time, $O(1)$ space.  Using Theorem~\ref{thm:split} one may evaluate the constant even branch in
$O(1)$ and loop only over odd $n$.

\textbf{Algorithm B (resonance enumeration).} Given $a$ and a bound $W$, enumerate
$R_a\cap(0,W]=\{(2m+1)/(2a-1): 0\le m<((2a-1)W-1)/2\}$, output-sensitive in $\Theta((2a-1)W)$ time; membership
testing is $O(1)$.

\textbf{Algorithm C (discriminator search).} Given a finite set $\mathcal{A}$ of multipliers, scan
$\omega=(2m+1)/(2a_0-1)$ for small $m$ and reject those $\omega$ for which some other $b\in\mathcal{A}$ satisfies
$(2b-1)\omega\in2\mathbb{Z}+1$.  By Theorem~\ref{thm:common} only odd integers must be rejected for the classical
multipliers, so the search terminates at $m=0$ with $\omega=1/(2a_0-1)$.

Numerically, with $a=3$ and $\omega=0.37$, $|F_3(\omega,N)/N-A_3(\omega)|$ equals $8.1\times10^{-3}$ at $N=10^3$ and
$1.3\times10^{-4}$ at $N=10^5$, comfortably inside Theorem~\ref{thm:error}.  At the resonance $\omega=1/5$ of the
$3n+1$ map, $|F_3(1/5,N)|\approx3.5,\,4.9,\,6.3,\,7.8$ at $N=10^2,10^3,10^4,10^5$: logarithmic growth, hence $o(N)$.
At the same frequency $|F_5|/N\to0.9511$ and $|F_7|/N\to0.5878$, matching Theorem~\ref{thm:disc}.  Midpoint
integration of $|A_a|^2$ over $[0,2]$ returns $0.50000000$ for $a=1,2,3,5,7,11,101$, confirming
Theorem~\ref{thm:meansq}.  Replacing the phase ratio by an arbitrary value at every power of two --- a set of
density zero --- changes the normalized transform by less than $4\times10^{-5}$ at $N=10^5$, illustrating
Theorem~\ref{thm:blind}.

\section{Discussion and future directions}

\subsection{What has been settled}
The one-step phase splits into a constant even branch $1/2$ and an odd branch $a+1/n$; the odd perturbation is
negligible after Ces\`aro averaging; hence $F_a(\omega,N)/N\to\bigl(e(\omega/2)+e(a\omega)\bigr)/2$ with modulus
$|\cos(\pi(a-\tfrac12)\omega)|$.  Every question about cancellation for the $an+1$ map at a fixed frequency is
answered at the level of the one-step sum, and by Theorem~\ref{thm:blind} the answer contains no dynamical
information.  Two methodological principles follow.  First, when a proposed pseudorandomness statistic is bounded
and its phase has finitely many accumulation points, its normalized limit should be computed before effort is spent
on cancellation bounds.  Second, a statistic invariant under density-zero surgery cannot imply any statement about
finite orbit data; testing for such invariance is cheap and decisive.

\subsection{Conjecture: the second-order law}

\begin{conjecture}[Second-order spectral law]\label{conj:second}
For every $a\ge1$ and every $\omega\ne0$, the quantity
\[
F_a(\omega,N)-N\,A_a(\omega)-c(a,\omega)\log N,\qquad c(a,\omega)=\pi i\,\omega\,e(a\omega),
\]
converges as $N\to\infty$; equivalently $\bigl(F_a(\omega,N)-NA_a(\omega)\bigr)/\log N\to c(a,\omega)$.
\end{conjecture}

The heuristic is the expansion $e(\omega/n)=1+2\pi i\omega/n+O(\omega^2/n^2)$ together with
$\sum_{n\le N,\,n\ \mathrm{odd}}1/n=\tfrac12\log N+O(1)$, so the deviation sum contributes
$e(a\omega)\cdot2\pi i\omega\cdot\tfrac12\log N$.  Theorem~\ref{thm:error} already isolates the deviation sum and
bounds it by $2\pi|\omega|(1+\log N)$; the conjecture asserts that this bound is attained with the stated constant.
Note that $c(a,\omega)$ carries the branch phase $e(a\omega)$ undamped and is linear in $\omega$: the subleading
spectrum sees strictly more than the leading one.  Numerically the convergence is slow, as expected for an
$O(1/\log N)$ correction: at $a=3$, $\omega=0.37$ the ratio moves from $-0.976+0.659i$ at $N=10^3$ to
$-0.859+0.777i$ at $N=10^6$, against the predicted $-0.741+0.896i$.

\subsection{Conjecture: iterated transforms are not blind}

\begin{conjecture}[Iterated limit law]\label{conj:iter}
For fixed $m\ge1$ let $F^{(m)}_a(\omega,N)=\sum_{n\le N}e\bigl(\omega\,T_a^m(n)/n\bigr)$.  Then
$F^{(m)}_a(\omega,N)/N$ converges to a finite combination $\sum_j 2^{-m}\mu_j\,e(\omega r_j)$, where the $r_j$ are the
finitely many limiting $m$-step ratios $a^{k}/2^{\,m-k}$ ($k$ the number of odd steps) and $\mu_j$ is the number of
residue classes mod $2^m$ following the corresponding parity pattern.  Moreover, for $m\ge2$ the resulting resonance
set is not a coset of a lattice, and its zero set determines $a$ uniquely.
\end{conjecture}

The point is structural: one step gives two branches and hence a cosine, whose zero set is an arithmetic progression
encoding only the integer $2a-1$.  Two steps give up to four branches with unequal weights, and a sum of four unit
vectors with rational weights has a zero set that is a genuine algebraic variety in $\omega$ rather than a lattice coset.

\subsection{Further directions}
\begin{itemize}
\item Replace the impossible global condition over all irrational frequencies by a condition excluding a fixed
neighbourhood of the integer resonances; by continuity, values near the zero-frequency peak necessarily remain near
the trivial bound $N$.
\item Study $F_a(\omega,N)/N$ on compact frequency sets bounded away from the integers and seek quantitative
cancellation estimates uniform in $N$, sharper than Theorem~\ref{thm:error}.
\item Exploit the explicit branch decomposition --- constant phase $1/2$ on evens, phase $a+1/n$ on odds --- to obtain
sharper asymptotics than treating the branches together.
\item Formulate averaged statements: $L^2$ bounds over a period, or bounds outside an exceptional set of small measure.
Such claims are compatible with isolated resonant peaks in a way that a pointwise bound over all irrationals is not,
though Theorem~\ref{thm:meansq} shows plain mean-square averaging is multiplier-blind.
\item Compare corrected normalized or averaged statistics for the $3n+1$, $5n+1$ and $7n+1$ maps.  Any useful
discriminator must depend on more than continuity near frequency zero.
\item Investigate orbit-dependent transforms separately from the one-step cutoff sum.  A rigorous implication between
an orbit hitting-time estimate and a spectral estimate requires precise definitions and directional proofs, and by
Corollary~\ref{cor:surgery} must not be treated as an automatic equivalence.
\end{itemize}

\section{Conclusion}
The one-step spectral transform of the $an+1$ maps is completely solved.  Its normalized limit is
$\bigl(e(\omega/2)+e(a\omega)\bigr)/2$, with modulus the single cosine $|\cos(\pi(a-\tfrac12)\omega)|$ and resonance set
the arithmetic progression $\{(2m+1)/(2a-1)\}$.  Convergence holds with an explicit $O\bigl((1+|\omega|\log N)/N\bigr)$
rate, uniformly in the multiplier and locally uniformly in the frequency.  Cancellation occurs exactly on the
resonance set; near frequency zero the transform is pinned to a quarter of the trivial bound, refuting any global
pointwise decay hypothesis; the mean square of the amplitude is the universal constant $\tfrac12$; and the whole
statistic is invariant under modification of the map on any density-zero set of inputs, hence carries no information
about cycles or hitting times.  What survives is the arithmetic of the resonance combs, which separates $3n+1$,
$5n+1$ and $7n+1$ pairwise at the frequencies $1/5$, $1/9$ and $1/13$.

